const src = porWebhook ? j0.body : j0;
for (const k of ['sessionId', 'texto']) {
  if (src[k] === undefined) throw new Error(`W6: falta "${k}"`);
}
return [{ json: {
  _via: porWebhook ? 'webhook' : 'subworkflow',
  sessionId: String(src.sessionId),
  contactId: src.contactId ?? null,
  opportunityId: src.opportunityId ?? null,
  texto: String(src.texto),
  evento: src.evento ?? null,
  primer_contacto: !!src.primer_contacto,
  fecha: $now.setZone('America/Mexico_City').toFormat("cccc dd/LL/yyyy HH:mm"),
} }];

function leerJSON(entrada) {
  let v = entrada;
  if (v && typeof v === 'object' && 'output' in v) v = v.output;
  if (typeof v === 'string') {
    let t = v.trim().replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
    const i = t.indexOf('{'), f = t.lastIndexOf('}');
    if (i >= 0 && f > i) t = t.slice(i, f + 1);
    try { v = JSON.parse(t); } catch (e) { return null; }
  }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  if (v.output && typeof v.output === 'object') v = v.output;   // doble envoltura
  // El prompt de Products escribe la clave CON TILDE ("subcategoría"); el resto del
  // sistema la usa sin tilde. Se aceptan las dos en vez de perder el filtro.
  if (v['subcategor\u00eda'] !== undefined && v.subcategoria === undefined) {
    v.subcategoria = v['subcategor\u00eda'];
  }
  return Object.keys(v).length ? v : null;
}

// El Router devuelve {step: "step_N"}.
