// Corrección al comentario anterior: el origen NO defaultea a step_4 "ante cualquier
// cosa rara". Su `Switch1` no tiene fallbackOutput y su única red es la regla 4 con
// `{{ $json.output.step || "step_4" }}`, que sólo cubre valores falsy. Con un step
// inválido pero no vacío (step_5, paso_3) el item MUERE ahí y el lead se queda sin
// respuesta, con la ejecución en verde. Acá se normaliza a step_4 a propósito: es
// más robusto que el origen, y queda declarado como tal.
const ctx = $('Normalizar entrada').first().json;
const o = leerJSON($input.first().json);
let step = (o && o.step) || 'step_4';
step = String(step).trim();
if (!/^step_[1-4]$/.test(step)) step = 'step_4';

