  }
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  if (v.output && typeof v.output === 'object') v = v.output;   // doble envoltura
  // El prompt de Products escribe la clave CON TILDE ("subcategoría"); el resto del
  // sistema la usa sin tilde. Se aceptan las dos en vez de perder el filtro.
  if (v['subcategor\u00eda'] !== undefined && v.subcategoria === undefined) {
    v.subcategoria = v['subcategor\u00eda'];
  }
  return Object.keys(v).length ? v : null;
}

// Toma la traducción del canonicalizador y la deja lista para W3. Si por lo que sea
// no devolvió una lista usable, se sigue con los nombres crudos del agente: perder
// precisión en el match es malo, quedarse sin mostrar nada es peor — y el origen
// tampoco corta acá.
const previo = $('Leer Products').first().json;
const o = leerJSON(($input.first().json || {}).message?.content) || {};
let productos = o.productos ?? [];
if (typeof productos === 'string') {
  const t = productos.trim();
  try { productos = t.startsWith('[') ? JSON.parse(t) : (t ? [t] : []); }
  catch (e) { productos = t ? [t] : []; }
}
if (!Array.isArray(productos)) productos = productos ? [productos] : [];
productos = productos.map(p => String(p).trim()).filter(Boolean);

return [{ json: { ...previo,
  productos: productos.length ? productos : previo.productos,
  productos_crudos: previo.productos,
  subcategoria: o.subcategoria || previo.subcategoria,
  canonicalizado: productos.length > 0 } }];

// Las cards del catálogo se convierten en burbujas: texto + su asset.
const ctx = $('Normalizar entrada').first().json;
const r = $input.first().json;
const step = $('Elegir ruta').first().json.step;
const cards = r.cards || [];
const partes = cards.map(c => ({
  texto: c.texto || c.nombre,
  adjuntos: c.media_url ? [c.media_url] : [],
}));

// El texto que acompaña a las fichas. Sin esto el lead recibe fotos y ninguna
// palabra: el oráculo muestra que el origen SIEMPRE mandaba un texto además de
// los assets (sample_1 T6 y T10, sample_9 T6 y T10).
//
//  · step_2 — la reacción al evento + la promo de 7 días, ANTES de la imagen
//    principal. En el origen viajaba por el salesbot 60862 de Kommo, fuera de
//    n8n; acá se usa el `texto_dinamico` que el propio Main Image ya genera y
//    que hasta ahora se descartaba.
//  · step_3 — el pedido de cantidad y código postal, DESPUÉS de las fichas.
//    En el origen es un texto FIJO, hardcodeado en el nodo `actualizar23`: no
//    sale del agente. Se replica literal.
//
// El orden (antes en step_2, después en step_3) sale de la semántica de cada
// texto, no de la topología del origen: allá los dos salían por ramas paralelas
// de Kommo y el orden real no es observable desde el grafo. Queda declarado.
const CTA_STEP_3 = '¿Le interesa sumarlos a la cotización?\n' +
  'Dígame:\n- Cantidad\n- Código postal\n\n¡Gracias!';

// El texto_dinamico no viene de W3 (que sólo sabe de fichas) sino del agente. Se lo
// pide al nodo lector, chequeando isExecuted: referenciar un nodo que no corrió en
// esta rama tira ExpressionError y se lleva puesto el turno entero.
let dinamico = '';
if (step === 'step_2') {
  const li = $('Leer Main Image');
  dinamico = String((li.isExecuted ? li.first().json.texto_dinamico : '') || '').trim();
}

if (step === 'step_2' && dinamico) {
  partes.unshift({ texto: dinamico, adjuntos: [] });
} else if (step === 'step_3') {
  partes.push({ texto: CTA_STEP_3, adjuntos: [] });
}

if (partes.length === 0) {
  partes.push({ texto: 'Déjame revisar eso y te confirmo.', adjuntos: [] });
}
return [{ json: {
  ok: true, sessionId: ctx.sessionId, contactId: ctx.contactId,
  step, partes, sin_media: r.sin_media || [], tools_usadas: ['CATALOGO'],
  // El evento viaja para que los seguimientos puedan interpolarlo en sus textos
  // (las olas 1 y 3 de la campaña `imagen` dicen "vi que me comentaste {evento}").
  evento: r.evento || null,
  // W6 decide la etapa, W1 la escribe. Réplica de seg-imagen (ETAPA 2) y
  // seg-cotizacion (ETAPA 3) del origen, que avanzan sin condición.
  etapa_destino: step === 'step_2' ? 'Evento Identificado' : 'Productos Mostrados',
} }];

