parameters.jsCode:
// Corta la respuesta del agente en burbujas. El origen usaba un LLM para esto
// (Message a model1, 13 KB de prompt). Acá es determinístico: mismo criterio de corte
// —párrafos— pero sin una llamada más ni la variabilidad de un modelo.
// REGLA HEREDADA: una cotización y el bloque de los 7 pasos NUNCA se parten.
const ctx = $('Normalizar entrada').first().json;
const salida = $input.first().json;
let txt = String(salida.output ?? salida.text ?? '').trim();
if (!txt) throw new Error('W6: el agente no devolvió texto');

// El modelo a veces envuelve toda la respuesta entre comillas (rectas o tipográficas)
// y eso llegaba al cliente tal cual: la primera burbuja abría con « y la última
// cerraba con ». En el origen lo absorbía el splitter LLM; acá hay que sacarlo.
const PAR = [['"', '"'], ['“', '”'], ["'", "'"], ['«', '»']];
for (const [a, b] of PAR) {
  if (txt.length > 1 && txt.startsWith(a) && txt.endsWith(b)) {
    txt = txt.slice(a.length, -b.length).trim();
    break;
  }
}

const INDIVISIBLE = /(Cotizaci[óo]n|Anticipo|7 SENCILLOS PASOS|7 DIAS DE PROMO)/i;

let partes;
if (INDIVISIBLE.test(txt)) {
  partes = [txt];                                  // entero, sin cortar
} else {
  partes = txt.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean);
  // el origen mandaba como máximo 3 burbujas
  if (partes.length > 3) {
    partes = [partes[0], partes[1], partes.slice(2).join('\n\n')];
  }
  if (partes.length === 0) partes = [txt];
}

const pasos = (salida.intermediateSteps || []).map(s => s?.action?.tool).filter(Boolean);
const step = $('Elegir ruta').first().json.step;

// step_3 con respuesta especial: el lead ya recibió las fichas y ahora recibe además
// la respuesta del Recolector. Las burbujas del catálogo van PRIMERO, como en el
// origen (Loop Over Items manda las fichas, y recién después corre el Recolector).
// isExecuted es obligatorio: en step_4 este nodo no corrió y referenciarlo tira
// ExpressionError, que se llevaría puesto el turno entero.
const ca = $('Cards a partes');
const fichas = ca.isExecuted ? (ca.first().json.partes || []) : [];
const partesFinales = fichas.concat(partes.map(p => (typeof p === 'string'
  ? { texto: p, adjuntos: [] } : p)));

// Etapa destino. W6 decide, W1 escribe.
//   step_1 → Saludo Enviado. NOTA: es capacidad NUEVA. En Kommo la ETAPA 1 se LEE
//     (If8, If21) pero ningún nodo de n8n la escribe; el saludo salía por salesbots
//     cuyo cuerpo no está en el export, así que quién la escribía no es verificable
//     desde el repo. En GHL no hay salesbots: si no la escribe W1, no la escribe nadie.
//   step_4 → Cotizado SÓLO si el Recolector realmente cotizó. Es la condición `If4`
//     del origen (`output` contains "7 DIAS DE PROMO") antes de mover a ETAPA 4. Un
//     "¿cuánto sale un cilindro?" ruteado a step_4 NO avanza la etapa. Se reusa la
//     misma regex INDIVISIBLE de arriba en vez de inventar otra.
let etapa_destino = null;
if (step === 'step_1') etapa_destino = 'Saludo Enviado';
else if (step === 'step_3') etapa_destino = INDIVISIBLE.test(txt)
  ? 'Cotizado' : 'Productos Mostrados';
else if (step === 'step_4' && INDIVISIBLE.test(txt)) etapa_destino = 'Cotizado';

return [{ json: {
  ok: true,
  sessionId: ctx.sessionId, contactId: ctx.contactId,
  step,
  partes: partesFinales,
  tools_usadas: fichas.length ? ['CATALOGO'].concat(pasos) : pasos,
  texto_completo: txt,
  etapa_destino,
} }];
